class Solution { private lateinit var expression:String;private var index=0;fun parseBoolExpr(expression:String):Boolean{this.expression=expression;index=0;return parse()};private fun parse():Boolean{val ch=expression[index++];if(ch=='t')return true;if(ch=='f')return false;index++;if(ch=='!'){val value=!parse();index++;return value};var value=ch=='&';while(true){val next=parse();value=if(ch=='&')value&&next else value||next;if(expression[index]==')'){index++;return value};index++}} }
